/**
 * `api_keys` — Developer Platform integration tokens (Phase 11).
 *
 * Tokens are generated by users inside a workspace and authenticate the
 * Notion-compatible `/v1` REST API. Only the SHA-256 digest of the token is
 * persisted; the plaintext `secret_...` value is returned exactly once at
 * creation time, mirroring how Notion handles internal integration secrets.
 */

import { sql } from 'drizzle-orm';
import {
  index,
  jsonb,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
  varchar,
} from 'drizzle-orm/pg-core';

import { users } from './users.js';
import { workspaces } from './workspaces.js';

/** Capability scopes an integration token may carry. */
export const API_KEY_CAPABILITIES = [
  'read',
  'write',
  'manage',
  'webhooks',
  'automations',
] as const;

/** A single capability scope granted to an integration token. */
export type ApiKeyCapability = (typeof API_KEY_CAPABILITIES)[number];

/** Every capability scope, used as the default grant for new keys. */
export const DEFAULT_API_KEY_CAPABILITIES: readonly ApiKeyCapability[] = [
  'read',
  'write',
];

export const apiKeys = pgTable(
  'api_keys',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** Human label shown in the integration management UI. */
    name: varchar('name', { length: 255 }).notNull(),
    /** SHA-256 hex digest of the plaintext `secret_...` token. */
    tokenHash: text('token_hash').notNull(),
    /** Leading characters of the token, safe to display in logs/UI. */
    tokenPrefix: varchar('token_prefix', { length: 32 }).notNull(),
    capabilities: jsonb('capabilities')
      .$type<ApiKeyCapability[]>()
      .notNull()
      .default(sql`'["read","write"]'::jsonb`),
    createdById: uuid('created_by_id').references(() => users.id, {
      onDelete: 'set null',
    }),
    /** Last successful authentication time (audit / stale-key cleanup). */
    lastUsedAt: timestamp('last_used_at', { withTimezone: true, mode: 'date' }),
    expiresAt: timestamp('expires_at', { withTimezone: true, mode: 'date' }),
    /** Soft-revocation marker; revoked keys never authenticate again. */
    revokedAt: timestamp('revoked_at', { withTimezone: true, mode: 'date' }),
    createdAt: timestamp('created_at', { withTimezone: true, mode: 'date' })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    uniqueIndex('idx_api_keys_token_hash').on(table.tokenHash),
    index('idx_api_keys_workspace').on(table.workspaceId),
    index('idx_api_keys_revoked').on(table.revokedAt),
  ],
);

export type ApiKeyRow = typeof apiKeys.$inferSelect;
export type NewApiKeyRow = typeof apiKeys.$inferInsert;
